254	/* Route chunks a signed-in merchant navigates between. Warmed one at a time
255	   during browser idle after first paint, so by the time they tap the dock the
256	   chunk is already cached and Suspense never shows the full-screen loader —
257	   the framer-motion page transition runs back-to-back instead. Vite dedupes
258	   these import() calls with the lazy() ones above (same module = same chunk).
259	   Ordered by likelihood of being the next tap. */
260	const MOBILE_PRELOAD_ROUTES: Array<() => Promise<unknown>> = [
261	  () => import("@/pages/dashboard"),
262	  () => import("@/pages/merchant-terminal-mobile-v2"),
263	  () => import("@/pages/transactions"),
264	  () => import("@/pages/stock-management"),
