301	/* Sequential (not Promise.all) so warming never competes with the page's own
302	   data fetches for bandwidth; each chunk waits for the next idle slice. */
303	function useRoutePreload(enabled: boolean, deviceClass: DeviceClass) {
304	  useEffect(() => {
305	    if (!enabled) return;
306	    const routes = deviceClass === "mobile" ? MOBILE_PRELOAD_ROUTES : DESKTOP_PRELOAD_ROUTES;
307	    let stopped = false;
308	    let i = 0;
309	    const idle = (cb: () => void) =>
310	      "requestIdleCallback" in window
311	        ? (window as any).requestIdleCallback(cb, { timeout: 2000 })
312	        : setTimeout(cb, 250);
313	    const next = () => {
314	      if (stopped || i >= routes.length) return;
315	      routes[i++]()
316	        .catch(() => {}) // offline / chunk 404 — the lazy() route will surface it if actually visited
317	        .finally(() => idle(next));
318	    };
319	    // Head start for first paint + the auth check before saturating the pipe.
320	    const t = setTimeout(() => idle(next), 1000);
321	    return () => { stopped = true; clearTimeout(t); };
322	  }, [deviceClass, enabled]);
323	}
