340	/**
341	 * The recovery screen for "we could not find out whether you are signed in".
342	 *
343	 * Deliberately built from nothing: no lazy chunk, no shared component, no data
344	 * of its own. It is shown precisely when the backend is failing, which is the
345	 * worst possible moment to depend on it for anything.
346	 */
347	function AuthUnavailable({ detail, isRetrying, onRetry, onSignOut }: {
348	  detail: string | null;
349	  isRetrying: boolean;
350	  onRetry: () => void;
351	  onSignOut: () => void;
352	}) {
353	  return (
354	    <div
355	      data-testid="auth-unavailable"
356	      role="alert"
357	      className="min-h-screen flex items-center justify-center px-6"
358	      style={{ background: "#060D1F" }}
359	    >
360	      <div className="w-full max-w-sm text-center">
361	        <h1 className="text-white text-lg font-semibold">We couldn't check your session</h1>
362	        <p className="mt-3 text-sm leading-relaxed" style={{ color: "#9AA7C2" }}>
363	          {detail ?? "Something went wrong on our side."}
364	        </p>
365	        <p className="mt-2 text-sm leading-relaxed" style={{ color: "#9AA7C2" }}>
366	          You have not been signed out — your sign-in is still saved on this device.
367	        </p>
368	        <button
369	          type="button"
370	          data-testid="auth-unavailable-retry"
371	          onClick={onRetry}
372	          disabled={isRetrying}
373	          className="mt-6 w-full rounded-xl py-3 text-sm font-semibold disabled:opacity-60"
374	          style={{ background: "#00DFC8", color: "#04121F" }}
375	        >
376	          {isRetrying ? "Trying again…" : "Try again"}
377	        </button>
378	        <button
379	          type="button"
380	          data-testid="auth-unavailable-signout"
381	          onClick={onSignOut}
382	          className="mt-3 w-full rounded-xl py-3 text-sm font-medium"
383	          style={{ border: "1px solid rgba(255,255,255,0.18)", color: "#9AA7C2" }}
384	        >
385	          Sign out
386	        </button>
387	      </div>
388	    </div>
389	  );
390	}
391	
392	// Auth is checked ONCE at app load and cached here. ProtectedRoute reads from
393	// this context so navigating between protected routes never shows a loader or
394	// makes a redundant API call — both of which would destroy page transitions.
395	type AuthData = {
396	  isAuthenticated: boolean;
397	  merchantId?: string | null;
398	  role?: string | null;
399	  onboardingCompleted?: boolean | null;
400	  gstRegistered?: boolean;
401	  tradeGstMode?: "inclusive" | "exclusive";
402	};
403	
404	function isRecord(value: unknown): value is Record<string, unknown> {
405	  return typeof value === "object" && value !== null && !Array.isArray(value);
406	}
407	
408	/**
409	 * A parseable 200 is not sufficient proof of a session. Proxies and partial
410	 * deploys can return `{}` (or an HTML error serialised as JSON), and treating
411	 * that as authenticated creates a contradictory UI with no merchant identity.
412	 */
413	function readMerchantAuthData(payload: unknown): AuthData {
414	  if (!isRecord(payload) || !isRecord(payload.user)) {
415	    throw new Error("Missing signed-in user");
416	  }
417	
418	  const user = payload.user;
419	  const validId = typeof user.id === "number" || typeof user.id === "string";
420	  const validMerchantId =
421	    user.merchantId === null ||
422	    typeof user.merchantId === "number" ||
423	    typeof user.merchantId === "string";
424	
425	  if (
426	    !validId ||
427	    typeof user.email !== "string" ||
428	    typeof user.role !== "string" ||
429	    !validMerchantId ||
430	    typeof user.onboardingCompleted !== "boolean"
431	  ) {
432	    throw new Error("Incomplete signed-in user");
433	  }
434	
435	  return {
436	    isAuthenticated: true,
437	    merchantId: user.merchantId === null ? null : String(user.merchantId),
438	    role: user.role,
439	    onboardingCompleted: user.onboardingCompleted,
440	    gstRegistered: user.gstRegistered === true,
441	    tradeGstMode: user.tradeGstMode === "exclusive" ? "exclusive" : "inclusive",
442	  };
443	}
444	
445	/**
446	 * `checking`     — the session check is in flight. Always bounded; see below.
447	 * `resolved`     — we know. `auth.isAuthenticated` is the answer.
448	 * `unavailable`  — we could not find out. The stored credentials have NOT been
449	 *                  touched, because nothing has disproved them.
450	 *
451	 * The third state is the whole point: without it, "the backend is broken" had
452	 * to be squeezed into "signed out", which silently destroyed live sessions
453	 * during an outage.
454	 */
455	type AuthPhase = "checking" | "resolved" | "unavailable";
456	
457	type AuthContextValue = {
458	  auth: AuthData | null;
459	  phase: AuthPhase;
460	  /** Why we could not check, for the recovery screen. Null unless unavailable. */
461	  detail: string | null;
462	  isRetrying: boolean;
463	  retry: () => void;
464	  signOut: () => void;
465	};
466	
467	// Exported (with AuthProvider and ProtectedRoute below) so the outage
468	// behaviour can be tested directly — these bounds are only worth anything if
469	// something proves they hold.
470	export const AuthContext = createContext<AuthContextValue>({
471	  auth: null,
472	  phase: "checking",
473	  detail: null,
474	  isRetrying: false,
475	  retry: () => {},
476	  signOut: () => {},
477	});
478	
479	/* ── Bounds on every session check ────────────────────────────────────────────
480	   `fetch` has no default timeout: a backend that accepts the connection and
481	   then never answers hands back a promise that never settles. That is exactly
482	   how this app once pinned itself on a full-screen loader with no way out.
483	   Every number below exists to make an unbounded wait unrepresentable —
484	   each attempt is aborted, the attempts are counted, and one deadline covers
485	   the entire sequence including the gaps between attempts.
486	   Invariant (asserted in the tests): the worst-case attempt sequence finishes
487	   inside the deadline, so the deadline is a backstop and not the normal exit. */
488	export const AUTH_ATTEMPT_TIMEOUT_MS = 4000;
489	export const AUTH_MAX_ATTEMPTS = 3;
490	export const AUTH_RETRY_DELAYS_MS = [300, 900];
491	export const AUTH_TOTAL_DEADLINE_MS = 14000;
492	
493	type ProbeOutcome<T> =
494	  /** The server answered and the session is good. */
495	  | { kind: "ok"; value: T }
496	  /** The server looked at the credentials/principal and refused them. */
497	  | { kind: "rejected" }
498	  /** We learned nothing about the credentials. Never a reason to discard them. */
499	  | { kind: "unavailable"; detail: string; retryable: boolean };
500	
501	type SessionResult<T> =
502	  | { kind: "ok"; value: T }
503	  | { kind: "rejected" }
504	  | { kind: "unavailable"; detail: string };
505	
506	function unreachableDetail(): string {
507	  return typeof navigator !== "undefined" && navigator.onLine === false
508	    ? "Your device looks offline. Check your connection and try again."
509	    : "The server didn't respond in time.";
510	}
511	
512	/**
513	 * Runs `probe` until it produces a definite answer, or until the bounds above
514	 * are spent — whichever comes first. `onResult` is called exactly once, with a
515	 * result that is never "still waiting".
516	 *
517	 * Returns a cancel function: after it runs, `onResult` can no longer fire, so
518	 * an unmounted consumer is never updated.
519	 */
520	function startBoundedSessionCheck<T>(
521	  probe: (signal: AbortSignal) => Promise<ProbeOutcome<T>>,
522	  onResult: (result: SessionResult<T>) => void,
523	): () => void {
524	  let settled = false;
525	  const timers = new Set<ReturnType<typeof setTimeout>>();
526	  const inFlight = new Set<AbortController>();
527	
528	  const stopEverything = () => {
529	    timers.forEach(clearTimeout);
530	    timers.clear();
531	    inFlight.forEach((controller) => controller.abort());
532	    inFlight.clear();
533	  };
534	
535	  // The single exit. First definite answer wins and cancels everything else, so
536	  // no straggler can revive the check or contradict the state it produced.
537	  const settle = (result: SessionResult<T>) => {
538	    if (settled) return;
539	    settled = true;
540	    stopEverything();
541	    onResult(result);
542	  };
543	
544	  const after = (ms: number, run: () => void) => {
545	    const id = setTimeout(() => {
546	      timers.delete(id);
547	      if (!settled) run();
548	    }, ms);
549	    timers.add(id);
550	    return id;
551	  };
552	
