622	  if (response.ok) {
623	    let payload: any = null;
624	    try {
625	      payload = await response.json();
626	    } catch {
627	      // A 200 we cannot parse is a proxy or a broken deploy talking, not a
628	      // verdict on the session.
629	      return { kind: "unavailable", detail: "The server sent a reply we couldn't read.", retryable: true };
630	    }
631	    try {
632	      return { kind: "ok", value: read(payload) };
633	    } catch {
634	      // A successful status with an incomplete body is a broken deploy, not a
635	      // valid identity. Keep the token and retry within the same hard bounds.
636	      return {
