export async function newRetailPage(browser, label, contextOptions) {
  const context = await browser.newContext({
    ...contextOptions,
    deviceScaleFactor: 1,
    serviceWorkers: "block",
    timezoneId: "Pacific/Auckland",
  });
  const page = await context.newPage();
  const errors = [];
  page.on("pageerror", (error) => errors.push(`${label} page: ${error.message}`));
  page.on("console", (message) => {
    if (message.type() === "error") errors.push(`${label} console: ${message.text()}`);
  });
  page.on("requestfailed", (request) => {
    errors.push(`${label} request failed: ${request.method()} ${request.url()} — ${request.failure()?.errorText ?? "unknown"}`);
  });
  page.on("response", (response) => {
    if (response.status() < 400) return;
    try {
      const url = new URL(response.url());
      if (url.origin !== new URL(BASE_URL).origin) return;
      errors.push(
        `${label} HTTP ${response.status()}: ${response.request().method()} ${url.pathname}${url.search}`,
      );
    } catch {
      errors.push(`${label} HTTP ${response.status()}: ${response.url()}`);
    }
  });
  await installRetailMocks(page);
  return { context, page, errors };
}

export async function runRetailShots(shoot) {
  const browser = await chromium.launch({ executablePath: CHROMIUM_PATH });
  try {
    const desktop = await shoot(browser, "desktop", {
      viewport: { width: 1440, height: 900 },
    });
    const tablet = await shoot(browser, "tablet", {
      viewport: { width: 1194, height: 834 },
      hasTouch: true,
      isMobile: false,
    });
    const errors = [...desktop, ...tablet];
    if (errors.length) throw new Error(`PAGE ERRORS:\n${errors.join("\n")}`);
    console.log("no page errors");
  } finally {
    await browser.close();
  }
}

