   closure: every selector below must stay an inline literal. Hoisting them to
   module constants would throw a ReferenceError inside the browser. */
const INSTRUMENT = () => {
  const w = window;
  if (w.__probe) return;
  w.__probe = { ev: [], t0: performance.now() };
