106	    // copy can never be stale — serve cache-first for instant repeat loads
107	    // and only hit the network for files we've never seen.
108	    event.respondWith(
109	      caches.open(STATIC_CACHE).then((cache) =>
110	        cache.match(request).then(
111	          (hit) =>
112	            hit ||
113	            fetch(request).then((response) => {
114	              if (response.ok) cache.put(request, response.clone());
115	              return response;
116	            })
117	        )
118	      )
119	    );
120	    return;
121	  }
122	
123	  if (url.pathname.match(/\.(js|css|woff2?|ttf|eot|svg|png|jpg|jpeg|gif|ico)$/)) {
124	    // Network-first with cache fallback: always try to get the freshest
125	    // asset first, only falling back to the cached copy if the network is
126	    // unavailable. This avoids serving stale JS/CSS/images indefinitely to
127	    // returning visitors after a new deploy (previously this was
128	    // cache-first-forever, which caused the landing page to look outdated
129	    // for anyone who had visited before, until the cache name was bumped).
130	    event.respondWith(
131	      fetch(request)
132	        .then((response) => {
133	          if (response.ok) {
134	            const clone = response.clone();
135	            caches.open(STATIC_CACHE).then((cache) => cache.put(request, clone));
136	          }
137	          return response;
138	        })
139	        .catch(() => caches.open(STATIC_CACHE).then((cache) => cache.match(request)))
140	    );
141	    return;
142	  }
143	
